const fs = require('fs');
const path = require('path');

/**
 * Reads the content of a file from a specified directory. If any error occurs during the file reading process (e.g., file not found, permission error), returns an empty string.
 *
 * @param {string} filename - The name of the file to read, requested by a user.
 * @param {string} dir_path - The directory path where the file is located.
 * @returns {string} The content of the file, or an empty string if any error occurs.
 */
function read_file_from_dir(filename, dir_path) {
  try {
    // Sanitize filename to prevent directory traversal
    const sanitizedFilename = path.basename(filename);

    // Resolve the absolute path of the directory
    const resolvedDirPath = path.resolve(dir_path);

    // Construct the full file path using the sanitized filename
    const filePath = path.join(resolvedDirPath, sanitizedFilename);

    // Resolve the absolute path of the constructed file path
    const resolvedFilePath = path.resolve(filePath);

    // Ensure the resolved file path is still within the intended directory
    // This check prevents directory traversal attacks.
    if (!resolvedFilePath.startsWith(resolvedDirPath)) {
      return '';
    }

    const fileContent = fs.readFileSync(resolvedFilePath, 'utf-8');
    return fileContent;
  } catch (error) {
    // Return an empty string if any error occurs during file reading
    return '';
  }
}
